import React, { useState, useEffect, useRef, useContext } from 'react';
import { useParams, Link } from 'react-router-dom';
import { CheckCircle2, PlayCircle } from 'lucide-react';
import { AuthContext } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import { API_URL } from '../config';

const CoursePlayer = () => {
  const { id } = useParams();
  const { token } = useContext(AuthContext);
  const [course, setCourse] = useState(null);
  const [activeLessonIndex, setActiveLessonIndex] = useState(0);
  const [completedIds, setCompletedIds] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const videoRef = useRef(null);

  useEffect(() => {
    fetch(`${API_URL}/courses/${id}`)
      .then(res => { if (!res.ok) throw new Error('Cours introuvable.'); return res.json(); })
      .then(data => setCourse(data))
      .catch(err => setError(err.message))
      .finally(() => setLoading(false));
  }, [id]);

  useEffect(() => {
    const videoEl = videoRef.current;
    if (videoEl) {
      videoEl.load();
      const playPromise = videoEl.play();
      if (playPromise !== undefined) {
        playPromise.catch(() => {});
      }
    }
  }, [activeLessonIndex, course]);

  const markLessonComplete = async (lessonId) => {
    if (!token) return;
    setCompletedIds((prev) => [...new Set([...prev, lessonId])]);
    try {
      await fetch(`${API_URL}/courses/${id}/progress/${lessonId}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch {}
  };

  const goToNextLesson = () => {
    if (!course) return;
    const current = course.lessons[activeLessonIndex];
    if (current) markLessonComplete(current.id);
    if (activeLessonIndex < course.lessons.length - 1) {
      setActiveLessonIndex(activeLessonIndex + 1);
    }
  };

  if (loading) {
    return <div className="min-h-screen text-white"><Navbar /><p className="text-slate-500 text-sm text-center py-32">Chargement...</p></div>;
  }

  if (error || !course || course.lessons.length === 0) {
    return (
      <div className="min-h-screen text-white">
        <Navbar />
        <div className="flex flex-col items-center justify-center py-32 gap-4">
          <p className="text-slate-500 text-sm">{error || 'Aucune leçon disponible pour ce cours.'}</p>
          <Link to="/dashboard" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">← Retour à mon apprentissage</Link>
        </div>
      </div>
    );
  }

  const activeLesson = course.lessons[activeLessonIndex];
  const hasResume = course.resume_pdf_url && course.resume_pdf_url.trim() !== '';
  const hasTp = course.tp_pdf_url && course.tp_pdf_url.trim() !== '';
  const isLast = activeLessonIndex === course.lessons.length - 1;

  return (
    <div className="min-h-screen text-white">
      <Navbar />

      <div className="max-w-6xl mx-auto px-6 py-10">
        <div className="flex items-center gap-2 text-xs text-slate-500 mb-6">
          <Link to="/dashboard" className="hover:text-slate-300 transition-colors">Mon apprentissage</Link>
          <span>›</span>
          <span className="text-slate-300">{course.title}</span>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden">
          <div className="grid lg:grid-cols-[320px_1fr]">

            {/* Programme du cours — à gauche, dans le même cadre */}
            <div className="border-b lg:border-b-0 lg:border-r border-slate-800 max-h-[280px] lg:max-h-[520px] overflow-y-auto">
              <div className="flex items-center justify-between px-5 py-4 border-b border-slate-800 sticky top-0 bg-slate-900/95 backdrop-blur-sm">
                <h3 className="text-xs font-bold uppercase text-slate-400 tracking-wide">Programme du cours</h3>
                <span className="text-[11px] text-slate-500">{completedIds.length}/{course.lessons.length}</span>
              </div>
              <div className="p-2">
                {course.lessons.map((lesson, index) => {
                  const isActive = index === activeLessonIndex;
                  const isDone = completedIds.includes(lesson.id);
                  return (
                    <button
                      key={lesson.id}
                      onClick={() => setActiveLessonIndex(index)}
                      className={`w-full text-left flex items-center gap-3 px-3 py-3 rounded-xl text-sm transition-colors ${
                        isActive ? 'bg-blue-500/10 border border-blue-500/30 text-blue-400' : 'border border-transparent text-slate-300 hover:bg-slate-800/60'
                      }`}
                    >
                      <span className="shrink-0">
                        {isDone ? (
                          <CheckCircle2 size={18} className="text-emerald-400" />
                        ) : (
                          <PlayCircle size={18} className={isActive ? 'text-blue-400' : 'text-slate-600'} />
                        )}
                      </span>
                      <span className="flex-1 leading-snug">{lesson.title}</span>
                      <span className="text-[11px] font-mono text-slate-500 shrink-0">{lesson.duration}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Vidéo — à droite, même cadre, même ligne */}
            <div>
              <div className="bg-black aspect-video flex items-center justify-center">
                {activeLesson.video_url ? (
                  <video ref={videoRef} key={activeLesson.id} controls autoPlay className="w-full h-full">
                    <source src={activeLesson.video_url} />
                    Ton navigateur ne supporte pas la lecture vidéo.
                  </video>
                ) : (
                  <p className="text-slate-500 text-sm">Aucune vidéo n'a encore été ajoutée pour cette leçon.</p>
                )}
              </div>

              <div className="p-6">
                <div className="flex items-start justify-between gap-4 mb-6">
                  <div>
                    <span className="text-[11px] font-semibold text-blue-400 uppercase tracking-wide">{course.title}</span>
                    <h1 className="text-xl font-bold mt-1">{activeLesson.title}</h1>
                  </div>
                  {!isLast ? (
                    <button onClick={goToNextLesson} className="bg-blue-600 hover:bg-blue-500 text-white font-semibold text-sm px-5 py-2.5 rounded-lg transition-colors whitespace-nowrap shrink-0">
                      Leçon suivante →
                    </button>
                  ) : (
                    <button onClick={() => markLessonComplete(activeLesson.id)} className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-sm px-5 py-2.5 rounded-lg transition-colors whitespace-nowrap shrink-0">
                      Marquer comme terminé
                    </button>
                  )}
                </div>

                {(hasResume || hasTp) && (
                  <div className="grid sm:grid-cols-2 gap-4 pt-4 border-t border-slate-800">
                    {hasResume && (
                      <a href={course.resume_pdf_url} target="_blank" rel="noopener noreferrer"
                        className="flex items-center justify-between bg-slate-950 border border-slate-800 rounded-xl p-4 hover:border-blue-500/40 transition-colors">
                        <span className="text-sm font-semibold text-slate-200">Fiche Synthèse</span>
                        <span className="text-xs font-bold uppercase text-blue-400 bg-blue-500/10 px-3 py-1.5 rounded-lg">Télécharger</span>
                      </a>
                    )}
                    {hasTp && (
                      <a href={course.tp_pdf_url} target="_blank" rel="noopener noreferrer"
                        className="flex items-center justify-between bg-slate-950 border border-slate-800 rounded-xl p-4 hover:border-blue-500/40 transition-colors">
                        <span className="text-sm font-semibold text-slate-200">Travaux Pratiques</span>
                        <span className="text-xs font-bold uppercase text-blue-400 bg-blue-500/10 px-3 py-1.5 rounded-lg">Télécharger</span>
                      </a>
                    )}
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
};
export default CoursePlayer;
